 void ShowRow(string key,bool show){labels[key].Visible=rows[key].Visible=show;}
 void Filter(){string g=groups.SelectedItem as string,q=query.Text.Trim();actions.BeginUpdate();actions.Items.Clear();foreach(var a in engine.Actions.Where(a=>(g=="Все редакторы" || a.group==g) && (a.title+" "+a.description+" "+a.id).IndexOf(q,StringComparison.OrdinalIgnoreCase)>=0))actions.Items.Add(a);actions.EndUpdate();if(actions.Items.Count>0)actions.SelectedIndex=0;else SelectAction();}
 void Draw(object sender,DrawItemEventArgs e){if(e.Index<0)return;var a=(CampaignAction)actions.Items[e.Index];using(var b=new SolidBrush((e.State&DrawItemState.Selected)!=0?Color.FromArgb(57,53,43):Theme.Panel))e.Graphics.FillRectangle(b,e.Bounds);using(var f=new Font("Segoe UI",10,FontStyle.Bold))TextRenderer.DrawText(e.Graphics,a.title,f,new Rectangle(e.Bounds.X+10,e.Bounds.Y+5,e.Bounds.Width-20,44),Theme.Text,TextFormatFlags.WordBreak|TextFormatFlags.EndEllipsis);using(var f=new Font("Segoe UI",8))TextRenderer.DrawText(e.Graphics,Lang.T(a.group),f,new Rectangle(e.Bounds.X+10,e.Bounds.Y+49,e.Bounds.Width-20,17),Theme.Muted,TextFormatFlags.EndEllipsis);}
 void SelectAction(){selected=actions.SelectedItem as CampaignAction;picked=picked2=pickedTitle=pickedTitle2=null;objects.Items.Clear();lands.Clear();choices.Clear();foreach(var b in choiceButtons.Values)b.Text=Lang.T("Выбрать набор…");InvalidatePlan();if(selected==null){header.Text=Lang.T("РЕДАКТОР КАМПАНИИ");return;}header.Text=selected.title;header.Font=new Font("Segoe UI",15,FontStyle.Bold);info.Text=selected.description;var a=selected;labels["value"].Text=a.id.StartsWith("builder_person") || a.id=="builder_heir" || a.id=="map_new_vassal"?Lang.T("Возраст"):a.native=="war_score"?Lang.T("Счёт нападающего"):a.id=="scheme_slot_force" || a.id=="scheme_slot_remove"?Lang.T("Индекс места с 0"):a.id=="builder_artifact"?Lang.T("Качество"):Lang.T("Значение");labels["value2"].Text=a.id=="scheme_slot_force"?Lang.T("Удержание · месяцев"):a.id=="builder_artifact"?Lang.T("Богатство"):Lang.T("Второе значение");ShowRow("recipients",a.recipients);if(a.recipients && recipients.Text=="" && !mock)recipients.Text=String.Join(", ",session.State.People.Where(p=>p.Role=="Ребёнок").Select(p=>p.ID));foreach(string k in choiceButtons.Keys)ShowRow("choice_"+k,a.choices!=null && a.choices.Contains(k));for(int i=0;i<6;i++)ShowRow("stat_"+i,a.stats);ShowRow("land",a.multi);ShowRow("other",a.other);ShowRow("value",a.body.Contains("$VALUE") || a.native=="war_score");ShowRow("value2",a.body.Contains("$VALUE2"));ShowRow("text",a.body.Contains("$TEXT"));ShowRow("text2",a.body.Contains("$TEXT2"));ShowRow("arg",!String.IsNullOrEmpty(a.arg));ShowRow("arg2",!String.IsNullOrEmpty(a.arg2));ShowRow("title",System.Text.RegularExpressions.Regex.IsMatch(a.body,@"\$TITLE") || a.scope=="title_key");ShowRow("title2",a.body.Contains("$TITLE2"));ShowRow("province",a.body.Contains("$PROVINCE") || a.scope=="province" || a.id=="finish_selected_construction");bool obj=CampaignEngine.Iterators.ContainsKey(a.scope);ShowRow("read",obj);ShowRow("objects",obj);value.Value=a.value;value2.Value=a.value2;text.Text=a.text??"";text2.Text=a.text2??"";arg.Text=arg2.Text=Lang.T("Выбрать…");title.Text=title2.Text=Lang.T("Выбрать титул…");labels["arg"].Text=LabelFor(a.arg);labels["arg2"].Text=LabelFor(a.arg2);State();}
 string LabelFor(string k){var m=new Dictionary<string,string>{{"trait",Lang.T("Черта")},{"maa",Lang.T("Тип полка")},{"tenet",Lang.T("Догмат")},{"doctrine",Lang.T("Доктрина")},{"culture",Lang.T("Культура")},{"faith",Lang.T("Вера")},{"sex",Lang.T("Пол")},{"artifact_type",Lang.T("Тип артефакта")},{"artifact_visual",Lang.T("Внешний вид")},{"government",Lang.T("Правительство")},{"coat",Lang.T("Герб")},{"agent_type",Lang.T("Место агента")},{"scheme_modifier",Lang.T("Бонус интриги")},{"artifact_modifier",Lang.T("Бонусы артефакта")},{"tradition",Lang.T("Традиции")},{"education",Lang.T("Образование")},{"court_position",Lang.T("Должность")},{"council_position",Lang.T("Место в совете")}};return k!=null && m.ContainsKey(k)?m[k]:k??Lang.T("Параметр");}
