 uint ID(TextBox b,bool required=true){uint id;if(!UInt32.TryParse(b.Text,out id) || id==0){if(required)throw new InvalidOperationException(Lang.T("Нужен числовой внутренний ID: ")+b.AccessibleName);return 0;}return id;}
