 List<uint> ParseRecipients(){var result=new List<uint>();foreach(string part in System.Text.RegularExpressions.Regex.Split(recipients.Text.Trim(),@"[\s,;]+")){uint id;if(!UInt32.TryParse(part,out id) || id==0)throw new InvalidOperationException(Lang.T("В порядке получателей нужны числовые ID через запятую."));result.Add(id);}return result;}
 async Task ReadObjects(){objects.Items.Clear();foreach(var o in await engine.Collect(selected.scope,ID(actor)))objects.Items.Add(o);if(objects.Items.Count>0)objects.SelectedIndex=0;status.Text=Lang.T("Найдено объектов: ")+objects.Items.Count;}
 async Task Prepare(){if(selected==null)return;var p=Parameters();if(selected.scope=="title_key" && pickedTitle==null || System.Text.RegularExpressions.Regex.IsMatch(selected.body,@"\$TITLE") && pickedTitle==null)throw new InvalidOperationException(Lang.T("Выбери первый титул."));if(selected.body.Contains("$TITLE2") && pickedTitle2==null)throw new InvalidOperationException(Lang.T("Выбери второй титул."));if(mock){engine.Expand(selected,p);preview.Text=selected.title+Lang.T("\r\n\r\nДемонстрация интерфейса. Исполнение отключено.");return;}plan=await engine.Prepare(selected,p);preview.Text=plan.Preview;status.Text=Lang.T("Предпросмотр готов. Проверь конкретные цели перед выполнением.");}
 async Task Execute(){if(plan==null || mock)return;var ready=plan;plan=null;await engine.Execute(ready);preview.Text=Lang.T("Команда принята движком. Проверь результат в игре.");status.Text=engine.History.Last();try{new System.Media.SoundPlayer(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"assets","on.wav")).Play();}catch{}}
 void State(){if(prepare==null)return;prepare.Enabled=selected!=null && !busy;execute.Enabled=plan!=null && !busy && !mock;groups.Enabled=actions.Enabled=query.Enabled=fields.Enabled=find.Enabled=!busy;}
 async void Run(Func<Task> job){if(busy)return;busy=true;State();try{await job();}catch(Exception e){status.Text=e.Message;if(session!=null && session.LastReply!="")File.AppendAllText(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"CK3PersonalTrainer","engine.log"),"\r\n"+DateTime.Now+Lang.T(" Редактор\r\n")+session.LastReply);}finally{busy=false;State();}}
 void Find(){if(mock){status.Text=Lang.T("Поиск требует подключения к игре.");return;}using(var f=new PeopleSearchForm(engine,session)){if(f.ShowDialog(this)==DialogResult.OK && f.Choice!=null){other.Text=f.Choice.ID.ToString();status.Text=Lang.T("Выбран: ")+f.Choice;}}}
 async void OnEditorClosing(object sender,FormClosingEventArgs e){if(allowClose)return;e.Cancel=true;if(busy){status.Text=Lang.T("Дождись завершения команды перед закрытием.");return;}if(closing)return;closing=true;timer.Stop();try{if(!mock)await engine.Clear();}catch(Exception x){status.Text=x.Message;}finally{allowClose=true;Close();}}
}

